-- AFTER the migration: job_schedule_status honours link types and the task hierarchy (A2a). One transaction, rolled back.
-- Every check prints NOTICE 'PASS ...'. Source of truth is 20_after.template.sql; 20_after.sql is generated by gen-cases.mjs
-- (it inserts the A2 cases of the shared fixture and the SQL-only targeted cases at the @@ markers).
-- Parts: (1) everything Phase A's 20_after.sql asserts about job_schedule_status, copied verbatim so the legacy behaviour is
-- proven on the new body; (2) signature / shape / volatility / security / grants unchanged; (3) A2 cases; (4) link types the
-- CHECK refuses (constraint dropped inside the transaction) behave as FS.
-- MUTATION HARNESS: supabase/tests/a2a_status/mutations.json (23 mutants of the migration body, 3 marked equivalent with a reason).
--   node supabase/tests/d0c_common/mutate.mjs a2a_status     -> "mutation check passed: 20/20 mutants caught"
--   one mutant by hand: bash supabase/tests/d0c_common/run.sh a2a_status <mutated-migration.sql>   (exit 0 = caught, 1 = survived)
--   Each mutant is applied in place of the migration and only THIS file is run; a failing assertion (or a migration that no longer applies) = caught.
-- Identities as in phase_a_sql: ops = operations_tech C1, viewr, fin (no ops atoms), clnt (client-shaped, no erp_users row), anon.
BEGIN;

-- ===== (1) legacy behaviour, copied from supabase/tests/phase_a_sql/20_after.sql (sections 13, 14 and the status blocks of 16-18) =====
-- ===== 13. job_schedule_status contract (X21) =====
SELECT set_config('request.jwt.claim.sub', '', true);
CREATE FUNCTION pg_temp.st(j text, d date) RETURNS text LANGUAGE sql AS $$
  SELECT count(*)::text || ':' || coalesce(string_agg(status || '|' || coalesce(forecast_end::text, 'null') || '|' || coalesce(slip_days::text, 'null'), ','), '-')
    FROM job_schedule_status(j::uuid, d) $$;
CREATE FUNCTION pg_temp.mkjob(n text, st text, due date) RETURNS text LANGUAGE sql AS $$
  INSERT INTO jobs (id, company_id, job_no, status, due_date)
  VALUES (('b1000000-0000-0000-0000-0000000e' || lpad(n, 4, '0'))::uuid, 'c1000000-0000-0000-0000-000000000001', 'WO-S' || n, st, due)
  RETURNING id::text $$;
CREATE FUNCTION pg_temp.mktask(j text, ord int, s date, e date, p int, ms boolean, w numeric) RETURNS void LANGUAGE sql AS $$
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, progress, is_milestone, weight)
  VALUES ('c1000000-0000-0000-0000-000000000001', j::uuid, ord, 't' || ord, s, e, p, ms, w) $$;
DO $$
DECLARE j text;
BEGIN
  j := pg_temp.mkjob('1', 'Open', NULL);
  PERFORM t_expect('status: no tasks, no baseline, no due date -> one row On track, NULL forecast and slip', pg_temp.st(j, '2026-03-01'), '1:On track|null|null');
  j := pg_temp.mkjob('2', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-10', 0, false, NULL);
  PERFORM t_expect('status: tasks but neither baseline nor due date -> slip NULL, forecast set', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-11|null');
  j := pg_temp.mkjob('3', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, NULL, NULL, 0, false, NULL);
  PERFORM t_expect('status: only unscheduled tasks -> forecast NULL', pg_temp.st(j, '2026-03-01'), '1:On track|null|null');
  j := pg_temp.mkjob('4', 'Open', '2026-03-11');
  PERFORM t_expect('status: due date but no tasks -> slip NULL (no forecast)', pg_temp.st(j, '2026-03-01'), '1:On track|null|null');
  FOR j IN SELECT pg_temp.mkjob(x.n, x.s, '2026-03-11') FROM (VALUES ('5','Completed'),('6','Invoiced'),('7','Closed'),('8','On Hold')) x(n, s) LOOP
    PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-10', 0, false, NULL);
  END LOOP;
  PERFORM t_expect('status: Completed -> Complete (one row)', pg_temp.st('b1000000-0000-0000-0000-0000000e0005', '2026-03-01'), '1:Complete|2026-03-11|0');
  PERFORM t_expect('status: Invoiced -> Complete', pg_temp.st('b1000000-0000-0000-0000-0000000e0006', '2026-03-01'), '1:Complete|2026-03-11|0');
  PERFORM t_expect('status: Closed -> Complete', pg_temp.st('b1000000-0000-0000-0000-0000000e0007', '2026-03-01'), '1:Complete|2026-03-11|0');
  PERFORM t_expect('status: On Hold -> On hold (forecast still returned)', pg_temp.st('b1000000-0000-0000-0000-0000000e0008', '2026-03-01'), '1:On hold|2026-03-11|0');
  UPDATE jobs SET status = 'Completed', due_date = '2026-01-01' WHERE id = 'b1000000-0000-0000-0000-0000000e0005';
  PERFORM t_expect('status: Complete wins over a hugely late slip', pg_temp.st('b1000000-0000-0000-0000-0000000e0005', '2026-03-01'), '1:Complete|2026-03-11|69');
  PERFORM t_expect('status: unknown job id -> zero rows', pg_temp.st('aaaaaaaa-0000-0000-0000-000000000000', '2026-03-01'), '0:-');
END $$;

-- slip boundaries: task 03-01..03-10, 0%, today 03-01 -> forecast 03-11
DO $$
DECLARE j text; r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES ('10','2026-03-20','On track','-9'), ('11','2026-03-11','On track','0'), ('12','2026-03-10','At risk','1'),
                                 ('13','2026-03-06','At risk','5'), ('14','2026-03-05','Late','6')) v(n, due, want, slip) LOOP
    j := pg_temp.mkjob(r.n, 'Open', r.due::date);
    PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-10', 0, false, NULL);
    PERFORM t_expect('status: slip ' || r.slip || ' days -> ' || r.want, pg_temp.st(j, '2026-03-01'), '1:' || r.want || '|2026-03-11|' || r.slip);
  END LOOP;
  -- overdue incomplete milestone: lateCrit (overdue by 5 days = At risk, by 6 = Late); a completed one is ignored
  j := pg_temp.mkjob('20', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-15', '2026-03-15', 0, true, NULL);
  PERFORM t_expect('status: milestone overdue by 5 days -> At risk', pg_temp.st(j, '2026-03-20'), '1:At risk|2026-03-20|null');
  j := pg_temp.mkjob('21', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-14', '2026-03-14', 0, true, NULL);
  PERFORM t_expect('status: milestone overdue by 6 days -> Late', pg_temp.st(j, '2026-03-20'), '1:Late|2026-03-20|null');
  j := pg_temp.mkjob('22', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-01', 100, true, NULL);
  PERFORM t_expect('status: completed milestone in the past is fine -> On track', pg_temp.st(j, '2026-03-20'), '1:On track|2026-03-01|null');
  j := pg_temp.mkjob('23', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-14', '2026-03-14', 0, true, NULL);
  PERFORM t_expect('status: the same milestone not yet overdue (today = its date) -> On track', pg_temp.st(j, '2026-03-14'), '1:On track|2026-03-14|null');
  -- overdue incomplete ordinary task on the critical path
  j := pg_temp.mkjob('24', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-10', 50, false, NULL);
  PERFORM t_expect('status: incomplete critical task overdue by 10 days -> Late', pg_temp.st(j, '2026-03-20'), '1:Late|2026-03-06|null');
END $$;

-- precision (X20): the gap uses the 2 dp values. weights 199 and 1 over identical baselines, planned exactly 50.00 on 2026-01-05
CREATE FUNCTION pg_temp.mkbl(n text, p1 int, p2 int, lock_it boolean) RETURNS text LANGUAGE plpgsql AS $$
DECLARE j text;
BEGIN
  j := pg_temp.mkjob(n, 'Open', NULL);
  PERFORM set_config('app.baseline_rpc', 'on', true);
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, baseline_start, baseline_end, baseline_locked_at, progress, weight)
  VALUES ('c1000000-0000-0000-0000-000000000001', j::uuid, 1, 'heavy', '2026-01-01', '2026-01-10', CASE WHEN lock_it THEN '2026-01-01'::date END, CASE WHEN lock_it THEN '2026-01-10'::date END, CASE WHEN lock_it THEN now() END, p1, 199),
         ('c1000000-0000-0000-0000-000000000001', j::uuid, 2, 'light', '2026-01-01', '2026-01-10', CASE WHEN lock_it THEN '2026-01-01'::date END, CASE WHEN lock_it THEN '2026-01-10'::date END, CASE WHEN lock_it THEN now() END, p2, 1);
  PERFORM set_config('app.baseline_rpc', 'off', true);
  RETURN j;
END $$;
DO $$
BEGIN
  PERFORM t_expect('precision: overall 39.995 rounds half-up to 40.00, gap exactly -10.00 -> On track (not At risk)',
    pg_temp.st(pg_temp.mkbl('30', 40, 39, true), '2026-01-05'), '1:On track|2026-01-08|-2');
  PERFORM t_expect('precision: overall 39.99 -> gap -10.01 -> At risk',
    pg_temp.st(pg_temp.mkbl('31', 40, 38, true), '2026-01-05'), '1:At risk|2026-01-08|-2');
  PERFORM t_expect('precision: gap -10.00 exactly (40 vs 50) -> On track', pg_temp.st(pg_temp.mkbl('32', 40, 40, true), '2026-01-05'), '1:On track|2026-01-07|-3');
  PERFORM t_expect('precision: gap -11 -> At risk', pg_temp.st(pg_temp.mkbl('33', 39, 39, true), '2026-01-05'), '1:At risk|2026-01-08|-2');
  PERFORM t_expect('precision: gap +50 ahead of plan -> On track', pg_temp.st(pg_temp.mkbl('34', 100, 100, true), '2026-01-05'), '1:On track|2026-01-10|0');
  PERFORM t_expect('precision: no locked baseline -> the gap rule is not evaluated even when far behind',
    pg_temp.st(pg_temp.mkbl('35', 0, 0, false), '2026-01-05'), '1:On track|2026-01-15|null');
END $$;

-- multiple predecessors and lag: C waits for the later of A and B
CREATE FUNCTION pg_temp.mklink(t text, p text, lag int) RETURNS void LANGUAGE sql AS $$
  INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days)
  SELECT company_id, job_id, id, p::uuid, lag FROM job_tasks WHERE id = t::uuid $$;
CREATE FUNCTION pg_temp.tid(j text, ord int) RETURNS text LANGUAGE sql AS $$
  SELECT id::text FROM job_tasks WHERE job_id = j::uuid AND sort_order = ord $$;
DO $$
DECLARE j text;
BEGIN
  j := pg_temp.mkjob('40', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-05', 0, false, NULL);
  PERFORM pg_temp.mktask(j, 2, '2026-03-01', '2026-03-10', 0, false, NULL);
  PERFORM pg_temp.mktask(j, 3, '2026-03-11', '2026-03-15', 0, false, NULL);
  PERFORM t_expect('status: unlinked tasks all start today -> forecast = longest task', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-11|null');
  PERFORM pg_temp.mklink(pg_temp.tid(j, 3), pg_temp.tid(j, 1), 0);
  PERFORM t_expect('status: C after the short predecessor only', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-11|null');
  PERFORM pg_temp.mklink(pg_temp.tid(j, 3), pg_temp.tid(j, 2), 0);
  PERFORM t_expect('status: C after BOTH predecessors starts after the later one (03-11 + 5)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-16|null');
  UPDATE job_task_links SET lag_days = 2 WHERE predecessor_id = pg_temp.tid(j, 2)::uuid;
  PERFORM t_expect('status: lag 2 days on the later link pushes the forecast to 03-18', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-18|null');
  UPDATE jobs SET due_date = '2026-03-10' WHERE id = j::uuid;
  PERFORM t_expect('status: due 03-10 vs forecast 03-18 -> slip 8 -> Late', pg_temp.st(j, '2026-03-01'), '1:Late|2026-03-18|8');
  -- a linked undated task takes part (1 day, starts today); a done undated task stays out
  j := pg_temp.mkjob('41', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-05', 0, false, NULL);
  PERFORM pg_temp.mktask(j, 2, NULL, NULL, 0, false, NULL);
  PERFORM pg_temp.mklink(pg_temp.tid(j, 2), pg_temp.tid(j, 1), 0);
  PERFORM t_expect('status: undated task linked after a dated one is scheduled (1 day after 03-06)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-07|null');
  -- a finished predecessor is not moved and its actual end drives the successor
  j := pg_temp.mkjob('42', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-02-01', '2026-02-10', 100, false, NULL);
  PERFORM pg_temp.mktask(j, 2, '2026-03-05', '2026-03-09', 0, false, NULL);
  PERFORM pg_temp.mklink(pg_temp.tid(j, 2), pg_temp.tid(j, 1), 0);
  PERFORM t_expect('status: done predecessor keeps its actual end; successor starts today (03-01 + 5)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-06|null');
END $$;

-- ===== 14. who can call job_schedule_status and what they get =====
DO $$
DECLARE ops uuid := '11111111-1111-1111-1111-111111111111'; ops2 uuid := '77777777-7777-7777-7777-777777777777';
  viewr uuid := '22222222-2222-2222-2222-222222222222'; fin uuid := '13131313-1313-1313-1313-131313131313';
  clnt uuid := 'cccccccc-cccc-cccc-cccc-cccccccccccc'; gone uuid := '66666666-6666-6666-6666-666666666666';
  q text := 'SELECT 1 FROM job_schedule_status(''b1000000-0000-0000-0000-0000000e0002''::uuid, ''2026-03-01'')';
BEGIN
  PERFORM t_expect('caller: operations_tech gets exactly one row', t_count('authenticated', ops, q), 'n:1');
  PERFORM t_expect('caller: viewer gets exactly one row', t_count('authenticated', viewr, q), 'n:1');
  PERFORM t_expect('caller: a member without work-order atoms gets zero rows (jobs RLS)', t_count('authenticated', fin, q), 'n:0');
  PERFORM t_expect('caller: a JWT with no company membership gets zero rows', t_count('authenticated', clnt, q), 'n:0');
  PERFORM t_expect('caller: inactive staff gets zero rows', t_count('authenticated', gone, q), 'n:0');
  PERFORM t_expect('caller: another company gets zero rows (invisible job)', t_count('authenticated', ops2, q), 'n:0');
  PERFORM t_expect('caller: anon cannot call it', t_count('anon', NULL, q), 'err:42501');
  PERFORM t_expect('caller: default p_today works (business-local date)',
    t_val('authenticated', ops, 'SELECT status FROM job_schedule_status(''b1000000-0000-0000-0000-0000000e0001''::uuid)'), 'On track');
  PERFORM t_expect('caller: status never NULL and always one of the five labels (all jobs, as postgres)',
    (SELECT count(*)::text FROM jobs j, LATERAL job_schedule_status(j.id, '2026-03-01') s
      WHERE s.status IS NULL OR s.status NOT IN ('On track','At risk','Late','Complete','On hold')), '0');
  PERFORM t_expect('caller: every job yields exactly one row',
    (SELECT count(*)::text FROM jobs j WHERE (SELECT count(*) FROM job_schedule_status(j.id, '2026-03-01')) <> 1), '0');
END $$;


-- (Phase A section 16, status blocks only)
DO $$
DECLARE j text;
BEGIN
  -- planned % keeps 2 dp inside the status: planned 33.33 vs overall 23 -> gap -10.33 -> At risk (a 0 dp planned of 33 would give -10)
  j := pg_temp.mkjob('50', 'Open', NULL);
  PERFORM set_config('app.baseline_rpc', 'on', true);
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, baseline_start, baseline_end, baseline_locked_at, progress, weight)
  VALUES ('c1000000-0000-0000-0000-000000000001', j::uuid, 1, 'p', '2025-12-20', '2026-01-03', '2026-01-01', '2026-01-03', now(), 23, 1);
  PERFORM set_config('app.baseline_rpc', 'off', true);
  PERFORM t_expect('precision: planned 33.33 is kept to 2 dp in the gap (gap -10.33 -> At risk)', pg_temp.st(j, '2026-01-01'), '1:At risk|2026-01-01|-2');
  -- remaining work rounds UP: 10 days at 33% -> 6.7 -> 7 days
  j := pg_temp.mkjob('51', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-01', '2026-03-10', 33, false, NULL);
  PERFORM t_expect('status: remaining work is rounded up (6.7 -> 7 days)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-08|null');
  -- an unstarted task is planned from today, not from its (future) start date
  j := pg_temp.mkjob('52', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-20', '2026-03-25', 0, false, NULL);
  PERFORM t_expect('status: unstarted task starts today in the forecast (6 days from 03-01)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-07|null');
  -- a started task keeps its actual start
  j := pg_temp.mkjob('53', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-02-20', '2026-03-01', 50, false, NULL);
  PERFORM t_expect('status: started task keeps its start (02-20 + ceil(10*0.5)=5 days)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-02-25|null');
  -- slack: a short overdue task OFF the critical path does not make the job late
  j := pg_temp.mkjob('54', 'Open', '2026-06-30');
  PERFORM pg_temp.mktask(j, 1, '2026-03-20', '2026-04-10', 0, false, NULL);
  PERFORM pg_temp.mktask(j, 2, '2026-03-01', '2026-03-05', 0, false, NULL);
  PERFORM t_expect('status: overdue short task has MORE slack than the long task, so it is not critical -> On track', pg_temp.st(j, '2026-03-20'), '1:On track|2026-04-11|-80');
END $$;

-- an overdue incomplete milestone counts even when it has slack (it is not on the longest path)
DO $$
DECLARE j text;
BEGIN
  j := pg_temp.mkjob('60', 'Open', NULL);
  PERFORM pg_temp.mktask(j, 1, '2026-03-20', '2026-04-30', 0, false, NULL);
  PERFORM pg_temp.mktask(j, 2, '2026-03-10', '2026-03-10', 0, true, NULL);
  PERFORM t_expect('status: overdue milestone with slack still makes the job Late (lateCrit covers every incomplete milestone)', pg_temp.st(j, '2026-03-20'), '1:Late|2026-05-01|null');
END $$;

-- locked-baseline cases: a milestone never counts in overall/planned; slip is measured against the baseline end, not the due date
SELECT set_config('request.jwt.claim.sub', '', true);
DO $$
DECLARE j text;
BEGIN
  j := pg_temp.mkjob('61', 'Open', NULL);
  PERFORM set_config('app.baseline_rpc', 'on', true);
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, baseline_start, baseline_end, baseline_locked_at, progress, is_milestone, weight) VALUES
   ('c1000000-0000-0000-0000-000000000001', j::uuid, 1, 'work', '2026-01-01', '2026-01-10', '2026-01-01', '2026-01-10', now(), 35, false, NULL),
   ('c1000000-0000-0000-0000-000000000001', j::uuid, 2, 'handover', '2026-01-20', '2026-01-20', '2026-01-20', '2026-01-20', now(), 100, true, 30);
  PERFORM set_config('app.baseline_rpc', 'off', true);
  PERFORM t_expect('status: a heavy-weighted done milestone must not hide a -15 gap (overall 35 vs planned 50) -> At risk', pg_temp.st(j, '2026-01-05'), '1:At risk|2026-01-20|0');
  j := pg_temp.mkjob('62', 'Open', '2026-03-05');
  PERFORM set_config('app.baseline_rpc', 'on', true);
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, baseline_start, baseline_end, baseline_locked_at, progress) VALUES
   ('c1000000-0000-0000-0000-000000000001', j::uuid, 1, 'work', '2026-03-01', '2026-03-10', '2026-03-01', '2026-03-11', now(), 0);
  PERFORM set_config('app.baseline_rpc', 'off', true);
  PERFORM t_expect('status: slip is forecast minus the BASELINE end (03-11), not the later-set due date (03-05)', pg_temp.st(j, '2026-03-01'), '1:On track|2026-03-11|0');
END $$;

-- ===== (2) the contract is unchanged: signature, return shape, STABLE, SECURITY INVOKER, search_path, grants =====
DO $$
DECLARE f text := 'public.job_schedule_status(uuid,date)';
BEGIN
  PERFORM t_expect('contract: exactly one job_schedule_status function (no overload)', (SELECT count(*)::text FROM pg_proc WHERE proname = 'job_schedule_status'), '1');
  PERFORM t_expect('contract: arguments (uuid, date with the business-local default)',
    (SELECT pg_get_function_arguments(f::regprocedure)), 'p_job_id uuid, p_today date DEFAULT (timezone(''America/Port_of_Spain''::text, now()))::date');
  PERFORM t_expect('contract: returns TABLE(status text, forecast_end date, slip_days integer)',
    (SELECT pg_get_function_result(f::regprocedure)), 'TABLE(status text, forecast_end date, slip_days integer)');
  PERFORM t_expect('contract: set-returning, plpgsql, STABLE, SECURITY INVOKER',
    (SELECT proretset::text || ',' || l.lanname || ',' || provolatile::text || ',' || prosecdef::text FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang WHERE p.oid = f::regprocedure),
    'true,plpgsql,s,false');
  PERFORM t_expect('contract: search_path pinned to public, pg_temp',
    (SELECT array_to_string(proconfig, ',') FROM pg_proc WHERE oid = f::regprocedure), 'search_path=public, pg_temp');
  PERFORM t_expect('contract: anon cannot execute', has_function_privilege('anon', f, 'EXECUTE')::text, 'false');
  PERFORM t_expect('contract: authenticated can execute', has_function_privilege('authenticated', f, 'EXECUTE')::text, 'true');
  PERFORM t_expect('contract: PUBLIC has no EXECUTE', (SELECT count(*)::text FROM pg_proc p, aclexplode(p.proacl) a WHERE p.oid = f::regprocedure AND a.grantee = 0), '0');
  PERFORM t_expect('contract: anon really gets 42501', t_val('anon', NULL, 'SELECT status FROM job_schedule_status(''b1000000-0000-0000-0000-0000000e0001''::uuid)'), 'err:42501');
  PERFORM t_expect('contract: no cost-like column or SELECT * in the body (Phase A rule)',
    (SELECT count(*)::text FROM pg_proc WHERE oid = f::regprocedure AND (prosrc ~* 'select +[*]' OR prosrc ~* '(_ttd|cost|price|margin)')), '0');
  PERFORM t_expect('contract: the body reads the A2 columns (not the Phase A body)',
    (SELECT (prosrc LIKE '%link_type%' AND prosrc LIKE '%parent_task_id%')::text FROM pg_proc WHERE oid = f::regprocedure), 'true');
END $$;

-- ===== (3) A2 cases =====
-- @@A2RUN@@

DO $$
BEGIN
-- @@CASES@@
END $$;

-- who can read an A2 job: the same RLS as Phase A (one row for members, zero for non-members, anon refused)
INSERT INTO jobs (id, company_id, job_no, status) VALUES ('b1000000-0000-0000-0000-0000000ea201', 'c1000000-0000-0000-0000-000000000001', 'WO-A2R1', 'Open');
INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date) VALUES
  ('f1000000-0000-0000-0000-0000000ea201', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 1, 'S', '2026-03-09', '2026-03-13'),
  ('f1000000-0000-0000-0000-0000000ea202', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 2, 'C1', '2026-03-09', '2026-03-13'),
  ('f1000000-0000-0000-0000-0000000ea203', 'c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 3, 'X', '2026-03-09', '2026-03-11');
UPDATE job_tasks SET parent_task_id = 'f1000000-0000-0000-0000-0000000ea201' WHERE id = 'f1000000-0000-0000-0000-0000000ea202';
INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days, link_type)
VALUES ('c1000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-0000000ea201', 'f1000000-0000-0000-0000-0000000ea203', 'f1000000-0000-0000-0000-0000000ea201', 0, 'SS');
DO $$
DECLARE ops uuid := '11111111-1111-1111-1111-111111111111'; ops2 uuid := '77777777-7777-7777-7777-777777777777';
  viewr uuid := '22222222-2222-2222-2222-222222222222'; fin uuid := '13131313-1313-1313-1313-131313131313';
  clnt uuid := 'cccccccc-cccc-cccc-cccc-cccccccccccc';
  q text := 'SELECT 1 FROM job_schedule_status(''b1000000-0000-0000-0000-0000000ea201''::uuid, ''2026-03-02'')';
BEGIN
  PERFORM t_expect('caller: operations_tech gets exactly one row for a hierarchy + SS-link job', t_count('authenticated', ops, q), 'n:1');
  PERFORM t_expect('caller: viewer gets one row', t_count('authenticated', viewr, q), 'n:1');
  PERFORM t_expect('caller: a member without work-order atoms gets zero rows', t_count('authenticated', fin, q), 'n:0');
  PERFORM t_expect('caller: a JWT with no company membership gets zero rows', t_count('authenticated', clnt, q), 'n:0');
  PERFORM t_expect('caller: another company gets zero rows', t_count('authenticated', ops2, q), 'n:0');
  PERFORM t_expect('caller: anon cannot call it', t_count('anon', NULL, q), 'err:42501');
  PERFORM t_expect('caller: the value an authenticated caller gets equals the owner value (SS from the summary: X starts with its leaf)',
    t_val('authenticated', ops, 'SELECT status || ''|'' || forecast_end::text FROM job_schedule_status(''b1000000-0000-0000-0000-0000000ea201''::uuid, ''2026-03-02'')'),
    (SELECT status || '|' || forecast_end::text FROM job_schedule_status('b1000000-0000-0000-0000-0000000ea201'::uuid, '2026-03-02')));
END $$;

-- ===== (4) link types the CHECK constraint refuses behave as FS (constraint dropped inside this rolled-back transaction) =====
DO $$
DECLARE cn text;
BEGIN
  SELECT conname INTO cn FROM pg_constraint WHERE conrelid = 'public.job_task_links'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) LIKE '%link_type%';
  PERFORM t_expect('unknown type: the link_type CHECK exists (so production data can never hold an unknown type)', (coalesce(cn, 'none') <> 'none')::text, 'true');
  PERFORM t_expect('unknown type: the CHECK lists exactly FS, SS, FF, SF',
    (SELECT (d LIKE '%''FS''%' AND d LIKE '%''SS''%' AND d LIKE '%''FF''%' AND d LIKE '%''SF''%' AND d NOT LIKE '%''ZZ''%')::text FROM (SELECT pg_get_constraintdef(oid) AS d FROM pg_constraint WHERE conname = cn) x), 'true');
  EXECUTE format('ALTER TABLE job_task_links DROP CONSTRAINT %I', cn);
END $$;
-- ===== (5) M1 (review 2): absurd dates a writer can store must not make the status function raise =====
DO $$
DECLARE
  c1 constant uuid := 'c1000000-0000-0000-0000-000000000001'; j constant uuid := 'b1000000-0000-0000-0000-0000000e9998'; r text;
BEGIN
  INSERT INTO jobs (id, company_id, job_no, status) VALUES (j, c1, 'WO-S9998', 'In Progress');
  INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date, progress) VALUES
    ('f1000000-0000-0000-0000-0000000e9981', c1, j, 1, 'far end', '2026-01-01', '99999-12-31', 0),
    ('f1000000-0000-0000-0000-0000000e9982', c1, j, 2, 'far both', '99998-01-01', '99999-12-31', 50),
    ('f1000000-0000-0000-0000-0000000e9983', c1, j, 3, 'ancient', '0100-01-01', '2026-02-01', 10),
    ('f1000000-0000-0000-0000-0000000e9984', c1, j, 4, 'done far', '2026-01-01', '99999-12-31', 100);
  BEGIN
    SELECT count(*)::text || '|' || (min(forecast_end) IS NOT NULL)::text INTO r FROM job_schedule_status(j, '2026-03-02');
  EXCEPTION WHEN OTHERS THEN r := 'raised: ' || SQLERRM;
  END;
  PERFORM t_expect('m1: dates in year 99999 and year 100 do not make job_schedule_status raise and still give a forecast', r, '1|true');
  DELETE FROM job_tasks WHERE job_id = j AND task_name IN ('far both', 'done far'); UPDATE job_tasks SET end_date = '2026-06-30' WHERE job_id = j AND task_name = 'far end';
  BEGIN SELECT count(*)::text INTO r FROM job_schedule_status(j, '2026-03-02'); EXCEPTION WHEN OTHERS THEN r := 'raised: ' || SQLERRM; END;
  PERFORM t_expect('m1: and still answers after the far dates are edited back', r, '1');
  -- a start date far in the past is clamped too: the forecast of a lone ancient task stays inside the clamp range
  DELETE FROM job_tasks WHERE job_id = j AND task_name = 'far end';
  SELECT (min(forecast_end) >= DATE '2000-01-01')::text INTO r FROM job_schedule_status(j, '2026-03-02');
  PERFORM t_expect('m1: a lone task starting in year 100 forecasts inside the clamp range', r, 'true');
END $$;

-- ===== (6) M2 (review 2): a long dependency chain settles in a few passes whatever order the links are stored in =====
-- 2503 tasks (prime, so (i * 37) % n is a permutation: the chain order is scrambled against the task order). Each task is 2 days, unstarted, so the
-- forecast is today + 2 * n; the first task of the chain is in the past, so the job is Late only when the backward pass reached it (it is critical).
-- Before the fix this took about 6 s (a pass per task); each call is timed and must finish in under 3 s (the fixed function needs about 0.4 s).
-- (statement_timeout cannot do this inside a DO block: it only applies to the statement that is already running.)
DO $$
DECLARE
  c1 constant uuid := 'c1000000-0000-0000-0000-000000000001';
  n constant integer := 2503; k integer := 0; shape text; j uuid; ord text; step text; res text; t0 timestamptz; secs numeric;
  s constant uuid := 'f9000000-0000-0000-0000-0000000000a0'; xx constant uuid := 'f9000000-0000-0000-0000-0000000000a1';
BEGIN
  FOREACH shape IN ARRAY ARRAY['asc', 'desc', 'random', 'skip'] LOOP
    k := k + 1;
    j := ('b9000000-0000-0000-0000-0000000000' || lpad(k::text, 2, '0'))::uuid;
    ord := CASE shape WHEN 'asc' THEN 'a.cp' WHEN 'desc' THEN 'a.cp DESC' ELSE 'md5(a.id::text || b.id::text)' END;
    step := CASE shape WHEN 'skip' THEN 'b.cp IN (a.cp + 1, a.cp + 2)' ELSE 'b.cp = a.cp + 1' END;
    INSERT INTO jobs (id, company_id, job_no, status) VALUES (j, c1, 'WO-P' || k, 'In Progress');
    SET LOCAL session_replication_role = replica;
    INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, progress)
      SELECT c1, j, i, 'T' || i, CASE WHEN cp = 1 THEN DATE '2026-02-20' ELSE DATE '2026-03-02' END, CASE WHEN cp = 1 THEN DATE '2026-02-21' ELSE DATE '2026-03-03' END, 0
        FROM (SELECT i, ((i * 37) % n) + 1 AS cp FROM generate_series(1, n) i) q;
    EXECUTE format('INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days)
      SELECT %L, %L, b.id, a.id, 0 FROM (SELECT id, ((sort_order * 37) %% %s) + 1 AS cp FROM job_tasks WHERE job_id = %L) a
        JOIN (SELECT id, ((sort_order * 37) %% %s) + 1 AS cp FROM job_tasks WHERE job_id = %L) b ON %s ORDER BY %s', c1, j, n, j, n, j, step, ord);
    SET LOCAL session_replication_role = origin;
    t0 := clock_timestamp();
    SELECT x.status || '|' || x.forecast_end::text INTO res FROM job_schedule_status(j, DATE '2026-03-02') x;
    secs := extract(epoch FROM clock_timestamp() - t0);
    PERFORM t_expect('m2: a ' || n || '-task chain with links stored ' || shape || ' gives the right answer (Late: the critical first task is past)',
      res, 'Late|' || (DATE '2026-03-02' + 2 * n)::text);
    PERFORM t_expect('m2: ... and settles in under 3 s with links stored ' || shape, (secs < 3)::text, 'true');
  END LOOP;

  -- a summary with 1200 scrambled chained leaves and a task X that follows the summary (the link leaves a summary)
  j := 'b9000000-0000-0000-0000-0000000000f0';
  INSERT INTO jobs (id, company_id, job_no, status) VALUES (j, c1, 'WO-PH', 'In Progress');
  SET LOCAL session_replication_role = replica;
  INSERT INTO job_tasks (id, company_id, job_id, sort_order, task_name, start_date, end_date, progress) VALUES (s, c1, j, 0, 'S', DATE '2026-03-02', DATE '2026-03-03', 0), (xx, c1, j, 5000, 'X', DATE '2026-03-02', DATE '2026-03-03', 0);
  INSERT INTO job_tasks (company_id, job_id, sort_order, task_name, start_date, end_date, progress, parent_task_id)
    SELECT c1, j, i, 'L' || i, CASE WHEN cp = 1 THEN DATE '2026-02-20' ELSE DATE '2026-03-02' END, CASE WHEN cp = 1 THEN DATE '2026-02-21' ELSE DATE '2026-03-03' END, 0, s
      FROM (SELECT i, ((i * 37) % 1201) + 1 AS cp FROM generate_series(1, 1200) i) q;
  INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days)
    SELECT c1, j, b.id, a.id, 0 FROM (SELECT id, ((sort_order * 37) % 1201) + 1 AS cp FROM job_tasks WHERE job_id = j AND parent_task_id = s) a
      JOIN (SELECT id, ((sort_order * 37) % 1201) + 1 AS cp FROM job_tasks WHERE job_id = j AND parent_task_id = s) b ON b.cp = a.cp + 1 ORDER BY md5(a.id::text);
  INSERT INTO job_task_links (company_id, job_id, task_id, predecessor_id, lag_days) VALUES (c1, j, xx, s, 0);
  SET LOCAL session_replication_role = origin;
  t0 := clock_timestamp();
  SELECT x.status || '|' || x.forecast_end::text INTO res FROM job_schedule_status(j, DATE '2026-03-02') x;
  secs := extract(epoch FROM clock_timestamp() - t0);
  PERFORM t_expect('m2: a summary of 1200 chained leaves followed by a task: forecast is today + 2 * 1200 + 2 (the status is the same as the engine gave before the ordering change)', res, 'On track|' || (DATE '2026-03-02' + 2402)::text);
  PERFORM t_expect('m2: ... and it settles in under 3 s', (secs < 3)::text, 'true');
END $$;

